class Cache:
    def __init__(self):
        self._data = {}

    def put(self, tenant, key, value):
        self._data[f"cache:{tenant}:{key}"] = value

    def get(self, tenant, key):
        return self._data.get(f"cache:{tenant}:{key}")

    def invalidate(self, tenant, key):
        try:
            del self._data[f"cache:{tenant}:{key}"]
        except KeyError:
            return False
        return True
